-- E-commerce sample database (ecommerce-sample-database) v1 — mssql
-- Synthetic sample data, CC0-1.0. Deterministic: the same spec and seed produce this byte for byte.
-- seed: flagship:ecommerce-sample-database:1k
-- Engine 2 (faker 10.6.0), locale en_US. UTF-8.
-- Run with sqlcmd -f 65001 so the file is read as UTF-8.
-- Tables in dependency order; foreign keys are added after the data.



CREATE TABLE dbo.[brands] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [description] nvarchar(23) NOT NULL,
    [logo_url] nvarchar(39) NOT NULL,
    [name] nvarchar(114) NOT NULL
);

CREATE TABLE dbo.[categories] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [description] nvarchar(22) NOT NULL,
    [name] nvarchar(11) NOT NULL UNIQUE,
    [parent_category_id] int,
    [slug] nvarchar(120) NOT NULL UNIQUE
);

CREATE TABLE dbo.[countries] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [code] nvarchar(120) NOT NULL,
    [name] nvarchar(120) NOT NULL
);

CREATE TABLE dbo.[discount_coupons] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [code] nvarchar(9) NOT NULL UNIQUE,
    [discount_type] nvarchar(120) NOT NULL,
    [discount_value] decimal(14,2) NOT NULL,
    [ends_at] datetime2 NOT NULL,
    [is_active] bit NOT NULL,
    [min_purchase_amount] int NOT NULL,
    [starts_at] datetime2 NOT NULL
);

CREATE TABLE dbo.[order_statuses] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [description] nvarchar(23) NOT NULL,
    [status_name] nvarchar(9) NOT NULL UNIQUE
);

CREATE TABLE dbo.[payment_methods] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [name] nvarchar(14) NOT NULL UNIQUE
);

CREATE TABLE dbo.[product_attributes] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [name] nvarchar(12) NOT NULL UNIQUE,
    [type] nvarchar(120) NOT NULL
);

CREATE TABLE dbo.[products] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [brand_id] int NOT NULL,
    [category_id] int NOT NULL,
    [compare_at_price] decimal(14,2),
    [created_at] datetime2 NOT NULL,
    [description] nvarchar(25) NOT NULL,
    [is_active] bit NOT NULL,
    [name] nvarchar(59) NOT NULL,
    [price] decimal(14,2) NOT NULL,
    [sku] nvarchar(12) NOT NULL UNIQUE,
    [slug] nvarchar(10) NOT NULL UNIQUE
);

CREATE TABLE dbo.[product_attribute_values] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [attribute_id] int NOT NULL,
    [product_id] int NOT NULL,
    [value] nvarchar(30) NOT NULL
);

CREATE TABLE dbo.[product_images] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [alt_text] nvarchar(15) NOT NULL,
    [product_id] int NOT NULL,
    [sort_order] int NOT NULL,
    [url] nvarchar(38) NOT NULL UNIQUE
);

CREATE TABLE dbo.[return_reasons] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [reason_text] nvarchar(255) NOT NULL UNIQUE
);

CREATE TABLE dbo.[shipping_methods] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [base_cost] decimal(14,2) NOT NULL,
    [carrier] nvarchar(8) NOT NULL,
    [estimated_days] int NOT NULL,
    [name] nvarchar(12) NOT NULL UNIQUE
);

CREATE TABLE dbo.[suppliers] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [contact_name] nvarchar(62) NOT NULL,
    [email] nvarchar(78) NOT NULL,
    [name] nvarchar(114) NOT NULL,
    [phone] nvarchar(26) NOT NULL,
    [website] nvarchar(75) NOT NULL
);

CREATE TABLE dbo.[tax_rates] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [country_id] int NOT NULL,
    [rate] decimal(14,4) NOT NULL,
    [state_province] nvarchar(3) NOT NULL
);

CREATE TABLE dbo.[users] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [created_at] datetime2 NOT NULL,
    [email] nvarchar(78) NOT NULL UNIQUE,
    [first_name] nvarchar(30) NOT NULL,
    [last_name] nvarchar(44) NOT NULL,
    [password_hash] nvarchar(60) NOT NULL,
    [phone] nvarchar(26) NOT NULL,
    [updated_at] datetime2 NOT NULL
);

CREATE TABLE dbo.[addresses] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [city] nvarchar(40) NOT NULL,
    [country_id] int NOT NULL,
    [extended_address] nvarchar(7),
    [is_default_billing] bit NOT NULL,
    [is_default_shipping] bit NOT NULL,
    [postal_code] nvarchar(10) NOT NULL,
    [state_province] nvarchar(3) NOT NULL,
    [street_address] nvarchar(101) NOT NULL,
    [user_id] int NOT NULL
);

CREATE TABLE dbo.[audit_logs] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [action] nvarchar(6) NOT NULL,
    [performed_at] datetime2 NOT NULL,
    [record_id] int NOT NULL,
    [table_affected] nvarchar(9) NOT NULL,
    [user_id] int NOT NULL
);

CREATE TABLE dbo.[orders] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [billing_address_id] int NOT NULL,
    [coupon_id] int,
    [created_at] datetime2 NOT NULL,
    [discount_amount] decimal(14,2) NOT NULL,
    [order_status_id] int NOT NULL,
    [shipping_address_id] int NOT NULL,
    [shipping_cost] decimal(14,2) NOT NULL,
    [shipping_method_id] int NOT NULL,
    [subtotal] decimal(14,2) NOT NULL,
    [tax_amount] decimal(14,2) NOT NULL,
    [total] decimal(14,2) NOT NULL,
    [user_id] int NOT NULL
);

CREATE TABLE dbo.[order_items] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [discount_amount] int NOT NULL,
    [order_id] int NOT NULL,
    [product_id] int NOT NULL,
    [quantity] int NOT NULL,
    [tax_amount] decimal(14,2) NOT NULL,
    [unit_price] decimal(14,2) NOT NULL
);

CREATE TABLE dbo.[order_returns] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [order_item_id] int NOT NULL UNIQUE,
    [processed_at] datetime2 NOT NULL,
    [quantity] int NOT NULL,
    [reason_id] int NOT NULL,
    [requested_at] datetime2 NOT NULL,
    [status] nvarchar(9) NOT NULL
);

CREATE TABLE dbo.[payments] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [amount] decimal(14,2) NOT NULL,
    [order_id] int NOT NULL UNIQUE,
    [payment_method_id] int NOT NULL,
    [processed_at] datetime2 NOT NULL,
    [status] nvarchar(9) NOT NULL,
    [transaction_reference] nvarchar(16) NOT NULL UNIQUE
);

CREATE TABLE dbo.[product_reviews] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [comment] nvarchar(35),
    [created_at] datetime2 NOT NULL,
    [product_id] int NOT NULL,
    [rating] int NOT NULL,
    [title] nvarchar(21) NOT NULL,
    [user_id] int NOT NULL
);

CREATE TABLE dbo.[shipments] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [delivered_at] datetime2 NOT NULL,
    [order_id] int NOT NULL UNIQUE,
    [shipped_at] datetime2 NOT NULL,
    [tracking_number] nvarchar(18) NOT NULL UNIQUE
);

CREATE TABLE dbo.[shopping_carts] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [created_at] datetime2 NOT NULL,
    [updated_at] datetime2 NOT NULL,
    [user_id] int NOT NULL
);

CREATE TABLE dbo.[cart_items] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [added_at] datetime2 NOT NULL,
    [cart_id] int NOT NULL,
    [product_id] int NOT NULL,
    [quantity] int NOT NULL
);

CREATE TABLE dbo.[support_tickets] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [created_at] datetime2 NOT NULL,
    [priority] nvarchar(6) NOT NULL,
    [status] nvarchar(8) NOT NULL,
    [subject] nvarchar(26) NOT NULL,
    [user_id] int NOT NULL
);

CREATE TABLE dbo.[support_messages] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [message] nvarchar(36) NOT NULL,
    [sender_type] nvarchar(8) NOT NULL,
    [sent_at] datetime2 NOT NULL,
    [ticket_id] int NOT NULL
);

CREATE TABLE dbo.[warehouses] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [address] nvarchar(101) NOT NULL,
    [city] nvarchar(40) NOT NULL,
    [country_id] int NOT NULL,
    [name] nvarchar(13) NOT NULL UNIQUE
);

CREATE TABLE dbo.[product_inventories] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [product_id] int NOT NULL,
    [quantity_on_hand] int NOT NULL,
    [quantity_reserved] int NOT NULL,
    [reorder_level] int NOT NULL,
    [warehouse_id] int NOT NULL
);

CREATE TABLE dbo.[wishlists] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [created_at] datetime2 NOT NULL,
    [name] nvarchar(14) NOT NULL,
    [user_id] int NOT NULL
);

CREATE TABLE dbo.[wishlist_items] (
    [id] int IDENTITY(1,1) PRIMARY KEY,
    [added_at] datetime2 NOT NULL,
    [product_id] int NOT NULL,
    [wishlist_id] int NOT NULL
);

